-- Stratholme (map 329), Main Gate, 2026-11-20.
--
-- 1. Argent Crusaders 45346 (54 in the Main Gate streets) stand on top of the Scourge: in Cataclysm and later
--    they fight the undead as a backdrop (Pandaria 5.4.8 scripts them to attack the nearest one and deal no
--    damage). Here nothing started those fights, and any that did start were real: the crusaders and the
--    Scourge killed each other. Now they use our staged battle mechanism (staged-npc-battles.patch,
--    flags_extra 0x400: no damage from other creatures below 85% health) on both sides, and out of combat,
--    every 2-4 seconds, a crusader attacks the closest of 12 Scourge kinds within 8 yards (id 0-11). The
--    Scourge you pull from such a fight has at least 85% health; players do full damage as before.
--    The mounted Argent Crusaders 45456 of the Service Entrance get the flag too (no start rows).
-- 2. Ravaged Cadaver 10381 (15 spawns): unit_flags 294976 includes UNIT_FLAG_STUNNED 0x40000, so they never
--    fought back. Pandaria 5.4.8 has 32832, AzerothCore 64. Removed 0x40000.
-- 3. Movement: Pandaria 5.4.8 paths for the same guids (patrols, paths 329000001+), AzerothCore paths for two
--    Risen Monks and a Risen Guardsman, AzerothCore wander radius for 24 skeletons and cadavers. Bosses, the
--    crusaders, the questgivers and Fras Siabi are left alone.
--
-- The Main Gate packs match Pandaria 5.4.8 (the same 8.x layout); no overspawns removed.

-- 1. Argent Crusaders vs Scourge
UPDATE `creature_template` SET `flags_extra` = `flags_extra` | 1024 WHERE `entry` IN (45346, 45456, 10381, 10382, 10383, 10387, 10390, 10391, 10411, 10414, 10418, 10419, 10420, 10421, 10422, 10423, 10424, 10425, 10426, 11043, 11120, 42975);
DELETE FROM `smart_scripts` WHERE `entryorguid` = 45346 AND `source_type` = 0 AND `id` BETWEEN 0 AND 11;

-- 2. Ravaged Cadaver
UPDATE `creature_template` SET `unit_flags` = `unit_flags` & ~262144 WHERE `entry` = 10381; -- 0x40000

-- 3. Patrols
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 329000001 AND 329000999;
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2, `spawndist`=0 WHERE `map` = 329 AND `guid` IN (319972, 319974, 319986, 320080, 320122, 320129, 320134, 320137, 320138, 320141, 320159, 320199, 320200, 320222, 320225, 320249, 320252, 320258, 320269, 320359, 320364, 320365, 320372, 320373, 320376, 320377, 320378, 320379, 320381);

-- Random wandering (AzerothCore wander radius)
UPDATE `creature` SET `MovementType`=1, `spawndist`=2 WHERE `map` = 329 AND `MovementType`=0 AND `guid` IN (320035);
UPDATE `creature` SET `MovementType`=1, `spawndist`=5 WHERE `map` = 329 AND `MovementType`=0 AND `guid` IN (319920, 319921, 319922, 319940, 319941, 319945, 319957, 319962, 319967, 320020, 320022, 320023, 320026, 320028, 320030, 320044, 320047, 320095, 320108, 320136, 320142, 320149, 320250);

-- Check
SELECT CONCAT('Crusader start rows ', (SELECT COUNT(*) FROM `smart_scripts` WHERE `entryorguid` = 45346 AND `source_type` = 0),
              ', staged battle templates ', (SELECT COUNT(*) FROM `creature_template` WHERE `entry` IN (45346, 45456, 10381, 10382, 10383, 10387, 10390, 10391, 10411, 10414, 10418, 10419, 10420, 10421, 10422, 10423, 10424, 10425, 10426, 11043, 11120, 42975) AND `flags_extra` & 1024),
              ', Ravaged Cadaver stunned ', (SELECT (`unit_flags` & 262144) <> 0 FROM `creature_template` WHERE `entry` = 10381),
              ', patrols ', (SELECT COUNT(*) FROM `creature` WHERE `map` = 329 AND `MovementType` = 2),
              ', wanderers ', (SELECT COUNT(*) FROM `creature` WHERE `map` = 329 AND `MovementType` = 1)) AS `stratholme_main_gate`;
